#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class MetadataSignatureTask final {
public:
 enum class Kind {ReadVersion,Publish};enum class Stage {BindRom,BindFlash,Count,ReadRom,ReadStored,Compare,SelectMismatch,Decrement,Repeat,SelectMatch,ClearResult,SkipResult,BindResult,ReadVersion,BindSource,BindTarget,WritePage,Return,Complete};enum class Read {Rom,Stored,Version};
 explicit MetadataSignatureTask(Kind kind=Kind::ReadVersion):kind_(kind){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned index()const{return index_;}uint16_t result()const{return version_;}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::BindRom:case Stage::BindFlash:case Stage::BindResult:case Stage::BindSource:case Stage::BindTarget:return 9;case Stage::Count:return 6;case Stage::ReadRom:case Stage::ReadStored:return 5+c.read;case Stage::ReadVersion:return 12+c.read;case Stage::WritePage:return c.call;case Stage::Return:return c.ret;default:return 3;}}
 template<class R>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Count:remaining_=kind_==Kind::ReadVersion?40:48;break;case Stage::ReadRom:rom_=uint8_t(read(Read::Rom,index_));break;case Stage::ReadStored:stored_=uint8_t(read(Read::Stored,index_));++index_;break;case Stage::Compare:match_=rom_==stored_;break;case Stage::SelectMismatch:if(!match_)next=Stage::SelectMatch;break;case Stage::Decrement:--remaining_;break;case Stage::Repeat:if(remaining_)next=Stage::ReadRom;break;case Stage::SelectMatch:next=kind_==Kind::Publish?(match_?Stage::Return:Stage::BindSource):(match_?Stage::BindResult:Stage::ClearResult);break;case Stage::ClearResult:version_=0;break;case Stage::SkipResult:next=Stage::Return;break;case Stage::ReadVersion:version_=uint16_t(read(Read::Version,0));next=Stage::Return;break;case Stage::WritePage:waiting_=true;break;default:break;}stage_=next;return cost;}
private:Kind kind_;Stage stage_=Stage::BindRom;unsigned index_=0,remaining_=0;uint16_t version_=0;uint8_t rom_=0,stored_=0;bool match_=false,waiting_=false;
};
class MetadataGuardTask final {
public:enum class Stage {First,Advance,Compare,Select,Prepare,Write,Return,Complete};MetadataGuardTask(uint32_t buffer=0,uint16_t version=0,bool pair=false):stage_(pair?Stage::First:Stage::Compare),buffer_(buffer),version_(version),pair_(pair){}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool pair()const{return pair_;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}uint32_t buffer()const{return buffer_;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::First:return c.shortCall;case Stage::Advance:return 9;case Stage::Compare:return 6;case Stage::Write:return 12+c.write;case Stage::Return:return c.ret;default:return 3;}}
 template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::First:waiting_=true;break;case Stage::Advance:next=Stage::Complete;break;case Stage::Select:if(version_>0x807)next=Stage::Return;break;case Stage::Write:write(0);break;default:break;}stage_=next;return cost;}
private:Stage stage_;uint32_t buffer_;uint16_t version_;bool pair_=false,waiting_=false;};
class MetadataMigrationTask final {
public:enum class Stage {BindSource,CountPages,SelectSource,BindBuffer,CountBytes,Read,Write,Advance,Decrement,RepeatBytes,BindProgram,BindTarget,BindCheck,Guard,Program,AdvancePage,DecrementPage,RepeatPages,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned page()const{return page_;}unsigned index()const{return index_;}uint32_t source()const{return 0x220000+page_*256;}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::BindSource:case Stage::BindBuffer:case Stage::BindProgram:case Stage::AdvancePage:return 9;case Stage::CountPages:case Stage::CountBytes:return 6;case Stage::Read:return 5+c.read;case Stage::Write:return 3+c.write;case Stage::Guard:return c.shortCall;case Stage::Program:return c.call;case Stage::Return:return c.ret;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::CountPages:pages_=300;break;case Stage::CountBytes:bytes_=256;index_=0;break;case Stage::Read:value_=uint8_t(read(index_));break;case Stage::Write:write(index_,value_);break;case Stage::Advance:++index_;break;case Stage::Decrement:--bytes_;break;case Stage::RepeatBytes:if(bytes_)next=Stage::Read;break;case Stage::Guard:case Stage::Program:waiting_=true;break;case Stage::AdvancePage:++page_;break;case Stage::DecrementPage:--pages_;break;case Stage::RepeatPages:if(pages_)next=Stage::SelectSource;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::BindSource;unsigned page_=0,index_=0,pages_=0,bytes_=0;uint8_t value_=0;bool waiting_=false;};
class MetadataStartupTask final {
public:enum class Stage {ReadVersion,CompareVersion,SelectVersion,RetainVersion,BindUpdating,PrintUpdating,RestoreVersion,Migrate,BindUpdated,PrintUpdated,RetainDelay,CountSettling,RetainInner,CountDelay,TickDelay,RepeatDelay,ReleaseInner,TickSettling,RepeatSettling,ReleaseDelay,PublishMetadata,Return,Complete};enum class Child {None,Version,Print,Migration,Publish};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return child_!=Child::None;}Child child()const{return child_;}void resume(uint16_t result=0){if(child_==Child::Version)version_=result;child_=Child::None;}
 unsigned nextClocks(const FlashCredits&c)const{if(awaiting()||complete())return 0;switch(stage_){case Stage::ReadVersion:case Stage::PrintUpdating:case Stage::PrintUpdated:case Stage::PublishMetadata:return c.call;case Stage::Migrate:return c.shortCall;case Stage::CompareVersion:case Stage::CountSettling:case Stage::CountDelay:return 6;case Stage::RetainVersion:case Stage::RetainDelay:case Stage::RetainInner:return c.pushWord;case Stage::RestoreVersion:case Stage::ReleaseInner:case Stage::ReleaseDelay:return c.popWord;case Stage::BindUpdating:case Stage::BindUpdated:return 9;case Stage::Return:return c.ret;default:return 3;}}
 unsigned advanceBefore(unsigned budget,const FlashCredits&c){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::ReadVersion:child_=Child::Version;break;case Stage::SelectVersion:if(version_>0x807)next=Stage::PublishMetadata;break;case Stage::PrintUpdating:case Stage::PrintUpdated:child_=Child::Print;break;case Stage::Migrate:child_=Child::Migration;break;case Stage::CountSettling:settling_=500;break;case Stage::CountDelay:delay_=2663;break;case Stage::TickDelay:--delay_;break;case Stage::RepeatDelay:if(delay_)next=Stage::TickDelay;break;case Stage::TickSettling:--settling_;break;case Stage::RepeatSettling:if(settling_)next=Stage::RetainInner;break;case Stage::PublishMetadata:child_=Child::Publish;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::ReadVersion;Child child_=Child::None;uint16_t version_=0,settling_=0,delay_=0;};
}
